  const customers = listCustomers();
  const customer1 = customers.find((c) => c.id === 'C-003');
  const customer2 = customers.find((c) => c.id === 'C-007');
  const product = listProducts()[0];

  const inv1 = issueInvoice(
    createInvoice({
      customerId: customer1.id,
      issueDate: '2026-01-01',
      lines: [{ sku: product.sku, qty: 10, discountPercent: 0 }],
